/**
 * Generates the compact word lists used by the word games.
 *
 * Source: SCOWL (Spell Checker Oriented Word Lists) via the `wordlist-english`
 * package. Copyright 2000-2016 by Kevin Atkinson — see the notice embedded in
 * the generated files. Run with `npm run generate:words`; the output is
 * committed so the build never depends on this script.
 */
import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const require = createRequire(import.meta.url);
const lists = require('wordlist-english');
const outDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../src/games/_shared/words');

const onlyLetters = (w) => /^[a-z]+$/.test(w);

function collect(maxLevel) {
  const levels = ['10', '20', '35', '40', '50', '55', '60'].filter((l) => Number(l) <= maxLevel);
  const out = new Set();
  for (const l of levels) {
    for (const key of [`english/${l}`, `english/american/${l}`]) {
      for (const w of lists[key] ?? []) if (onlyLetters(w)) out.add(w);
    }
  }
  return out;
}

// Words we never want to present as an answer or seed. They may still be
// accepted as guesses if they appear in the validation dictionary.
const BLOCKED = new Set(
  `anal anus arse arses bitch bitches boner boob boobs booze bum butt crap cunt damn dick dildo drunk dyke fag fart fuck gay gays hell homo horny jerk kill kinky lust meth nazi nude nudes penis piss porn pussy queer rape raped rapes rapist scum semen sex sexy shit slut sperm suck tits turd urine vagina whore wank weed drugs drug slave slaves nigger negro devil satan bomb bombs bigot pimp crack gun guns knife kills death dead corpse murder`.split(
    /\s+/,
  ),
);

const isClean = (w) => ![...BLOCKED].some((b) => w === b || (b.length >= 4 && w.includes(b)));
const looksInflected = (w) =>
  (w.endsWith('s') && !w.endsWith('ss') && !w.endsWith('us') && !w.endsWith('is')) || w.endsWith('ed');

const dictionary = collect(50);
const guesses = collect(60);
const common = collect(20);

// ----- Validation dictionary (3–7 letters), packed per length.
const byLength = {};
for (const w of dictionary) {
  if (w.length < 3 || w.length > 7) continue;
  (byLength[w.length] ??= []).push(w);
}
for (const k of Object.keys(byLength)) byLength[k].sort();

// ----- Five Letters: answers (common, not inflected) + wider guess list.
const fiveAnswers = [...common].filter((w) => w.length === 5 && isClean(w) && !looksInflected(w)).sort();
const fiveGuesses = [...guesses].filter((w) => w.length === 5).sort();

// ----- Word Blitz seeds: common 7-letter words with rich sub-anagrams.
function subWords(seed) {
  const counts = {};
  for (const c of seed) counts[c] = (counts[c] ?? 0) + 1;
  const found = [];
  for (let len = 3; len <= seed.length; len++) {
    for (const w of byLength[len] ?? []) {
      const c2 = {};
      let ok = true;
      for (const c of w) {
        c2[c] = (c2[c] ?? 0) + 1;
        if (c2[c] > (counts[c] ?? 0)) {
          ok = false;
          break;
        }
      }
      if (ok) found.push(w);
    }
  }
  return found;
}
const blitzSeeds = [...common]
  .filter((w) => w.length === 7 && isClean(w) && !looksInflected(w))
  .filter((w) => {
    const n = subWords(w).length;
    return n >= 14 && n <= 70;
  })
  .sort();

const header = `/*
 * GENERATED by scripts/generate-wordlists.mjs — do not edit by hand.
 *
 * Word data derived from SCOWL (http://wordlist.aspell.net/).
 * Copyright 2000-2016 by Kevin Atkinson
 *
 * Permission to use, copy, modify, distribute and sell these word lists, the
 * associated scripts, the output created from the scripts, and its
 * documentation for any purpose is hereby granted without fee, provided that
 * the above copyright notice appears in all copies and that both that
 * copyright notice and this permission notice appear in supporting
 * documentation. Kevin Atkinson makes no representations about the
 * suitability of this array for any purpose. It is provided "as is" without
 * express or implied warranty.
 */
`;

const packed = Object.fromEntries(Object.entries(byLength).map(([k, v]) => [k, v.join('')]));
writeFileSync(
  path.join(outDir, 'dictionary.data.ts'),
  `${header}\n/** Words of each length concatenated without separators, sorted. */\nexport const PACKED_DICTIONARY: Readonly<Record<number, string>> = ${JSON.stringify(packed, null, 1)};\n`,
);
writeFileSync(
  path.join(outDir, 'five-letter.data.ts'),
  `${header}\n/** Curated answers (common, uninflected). Concatenated 5-letter words. */\nexport const FIVE_LETTER_ANSWERS = ${JSON.stringify(fiveAnswers.join(''))};\n\n/** Accepted guesses. Concatenated 5-letter words. */\nexport const FIVE_LETTER_GUESSES = ${JSON.stringify(fiveGuesses.join(''))};\n`,
);
writeFileSync(
  path.join(outDir, 'blitz-seeds.data.ts'),
  `${header}\n/** 7-letter seed words that contain a healthy number of sub-words. */\nexport const BLITZ_SEEDS = ${JSON.stringify(blitzSeeds.join(''))};\n`,
);

console.log(
  `dictionary: ${dictionary.size} words; five answers: ${fiveAnswers.length}; five guesses: ${fiveGuesses.length}; blitz seeds: ${blitzSeeds.length}`,
);
